    elements2.abilityDetailTag.textContent = detail.tag;
    elements2.abilityDetailDesc.textContent = detail.desc;
    elements2.abilityDetailScope.textContent = detail.scope;
    elements2.abilityDetailExample.textContent = detail.example;
    elements2.abilityDetail.hidden = false;
